sys_script_client.script:
function onLoad() {

    var assgn_to = g_form.getValue('assigned_to');
    var state1 = g_form.getValue('state');
    var trade_tt = g_form.getValue('trade_task_type');
    var userID = g_user.userID;
    //var dynamic_query = g_scratchpad.query;
    //var rows = g_scratchpad.rows;
    //var host = g_scratchpad.host;
    var nam = g_scratchpad.name;
    var time1 = g_scratchpad.time;
    var user_access = g_scratchpad.usr_access; //MSSCUSTODY-4911
    var user_was_maker = g_scratchpad.hasWorkedAsMaker; //MSSCUSTODY-4911

    g_form.setDisplay('lock', false);
    g_form.setDisplay('locktime', false);
    //var lo = g_form.getValue('locktime');
    //alert(lo);


    //MSSCUSTODY-8054
    if (g_scratchpad.cstReadOnly) {
		g_form.clearValue('assigned_to');
        makeFormReadOnly();
        return;
    }
    //MSSCUSTODY-8054



    //MSSCUSTODY-4911
    //FOR MANAGER AND CHECKER ROLES :
    if (trade_tt == 'Checker') {
        if (user_access) {
            if (hasUserWorkedOnTrade()) { //To check if the same user has worked on the trade as a maker
                makeFormReadOnly();
                alert('You cannot work on this task as you have actioned as a maker on this trade.');
                return;
            } else {
                if (state1 == '2' && assgn_to != g_user.userID && assgn_to != "") { //State is Work in Progress
                    if (!handleWorkInProgress(nam, userID)) { //Gives confirmation popup
                        return;
                    }
                } else if (state1 == '1' && (assgn_to == '' || assgn_to == null)) { //State is New
                    handleNewState(userID);
                }
            }
        } else {
            makeFormReadOnly();
        }
    }

    //FOR MAKER ROLE :
    if (trade_tt == 'Maker') {
        if ((user_access) && state1 == '2' && assgn_to != g_user.userID && assgn_to != "") {
            if (!handleWorkInProgress(nam, userID)) { //State is Work in Progress
                return;
            }
        } else if ((user_access) && state1 == '1' && (assgn_to == '' || assgn_to == null)) { //State is New		
            handleNewState(userID);
        } else if (!user_access) {
            makeFormReadOnly();
        }
    }

    //Function to make form read-only	
    function makeFormReadOnly() {
        var fields = g_form.getEditableFields();
        for (var i = 0; i < fields.length; i++) {
            g_form.setReadOnly(fields[i], true);
        }
    }

    //Function to make form editable
    function makeFormEditable() {
        var fields = g_form.getEditableFields();
        for (var i = 0; i < fields.length; i++) {
            g_form.setReadOnly(fields[i], false);
        }
    }

    //Function to check if user has already worked as Maker
    function hasUserWorkedOnTrade() {
        if (user_was_maker) {
            return true;
        }
        return false;
    }

    //Function to handle 'Work in Progress' state
    function handleWorkInProgress(nam, userID) {
        var ans = confirm("You are viewing a record which is already assigned to " + nam + ". Do you still want to work on it?");
        //If user clicks on 'Cancel', form becomes read only
        if (!ans) {
            makeFormReadOnly();
            return false;
        } else { //If user clicks on 'Ok', form gets assigned to him
            g_form.setValue('assigned_to', userID);
            g_form.setValue('lock', true);
            g_form.setValue('locktime', time1);
            makeFormEditable();
            g_form.save(); //MSSCUDTODY-6552
            return true;
        }
    }

    //Function to handle 'New' state
    function handleNewState(userID) {
        g_form.setValue('assigned_to', userID);
        g_form.setValue('lock', true);
        g_form.setValue('locktime', time1);
        g_form.save();
    }

}
